-- Phong Than 2026-10-03 (agent luyencong): give every character one "Lenh Bai Luyen Cong" (magicscript 61420).
-- Called once a minute from script\phongthan\newbie\starter_gear.lua (PTNB_LcTick, protected by PTAdm_Safe).
-- No main() here: this file is dofile'd into the servertimer state. Generated by scratchpad\luyencong\gen.py.
--  * task 2610 = 1 once the character owns the token (given here, or already in bag / box, e.g. from the web admin);
--  * set only after AddNormalItem really created it, so the gift waits for the ptfix row and for a free bag cell.
PTLC_GIVE_ITEM = 61420
PTLC_GIVE_TASK = 2610

-- current PlayerIndex: 1 if a token was given now
function PTLC_GiveOne()
	if GetTask(PTLC_GIVE_TASK) ~= 0 then return 0 end
	local have = HaveNormalItem(6, 1, PTLC_GIVE_ITEM, -1)
	if have and have > 0 then
		SetTask(PTLC_GIVE_TASK, 1)
		return 0
	end
	local r = AddNormalItem(6, 1, PTLC_GIVE_ITEM, 1, 0, 0)
	if r and r > 0 then
		SetTask(PTLC_GIVE_TASK, 1)
		Msg2Player("B\185n nh\203n \174\173\238c L\214nh B\181i Luy\214n C\171ng: nh\202p ph\182i \174\211 ch\228n b\183i luy\214n c\171ng theo c\202p v\181 d\222ch chuy\211n t\237i ngay ch\231 c\227 qu\184i. D\239ng v\220nh vi\212n, kh\171ng m\202t.")
		return 1
	end
	return 0
end

function PTLC_GiveTick()
	local i = 1
	local max = PTADM_MAX_PLAYER or 0
	while i <= max do
		PlayerIndex = i
		local nm = GetName()
		if nm and nm ~= "" then
			if PTLC_GiveOne() > 0 and PTAdm_Log then PTAdm_Log("luyencong", "OK", nm .. " +Lenh Bai Luyen Cong") end
		end
		i = i + 1
	end
	PlayerIndex = nil
end
